import{_ as o,r as s,o as p,c as l,e as a,a as c,s as i}from"./chunks/framework.CXcwiNg-.js";const f=JSON.parse('{"title":"定义选项 - October CMS - 3.x","titleTemplate":false,"description":"定义在许多定义中使用的 options 属性。","frontmatter":{"subtitle":"定义在许多定义中使用的 options 属性。"},"headers":[{"level":2,"title":"选项数组","slug":"选项数组","link":"#选项数组","children":[]},{"level":2,"title":"选项预设","slug":"选项预设","link":"#选项预设","children":[]},{"level":2,"title":"选项方法","slug":"选项方法","link":"#选项方法","children":[{"level":3,"title":"详细选项定义","slug":"详细选项定义","link":"#详细选项定义","children":[{"level":4,"title":"另请参阅","slug":"另请参阅","link":"#另请参阅","children":[]}]}]}],"relativePath":"3.x/zh-cn/element/define-options.md","filePath":"3.x/zh-cn/element/define-options.md"}'),r={name:"3.x/zh-cn/element/define-options.md"};function d(u,n,g,k,h,m){const t=s("pre-heading"),e=s("post-heading");return p(),l("div",null,[a(t),n[0]||(n[0]=c("h1",null,"定义选项",-1)),a(e),n[1]||(n[1]=i(`<p>通常，您可能会遇到 <strong>options</strong>、<strong>optionsMethod</strong> 或 <strong>optionsPreset</strong> 属性，本文更详细地描述了如何配置选项。</p><h2 id="选项数组"><a href="#选项数组" class="header-anchor">#</a> 选项数组</h2><p><code>options</code> 属性应直接在定义中以键值对的形式指定选项，其中值和标签是独立指定的。</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">options</span><span class="token punctuation">:</span>
    <span class="token key atrule">draft</span><span class="token punctuation">:</span> Draft
    <span class="token key atrule">published</span><span class="token punctuation">:</span> Published
    <span class="token key atrule">archived</span><span class="token punctuation">:</span> Archived
</code></pre></div><p>键可以是带有标签的整数。</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">options</span><span class="token punctuation">:</span>
    <span class="token key atrule">1</span><span class="token punctuation">:</span> Simple
    <span class="token key atrule">2</span><span class="token punctuation">:</span> Complex
</code></pre></div><p>除了简单数组外，某些字段（如 <a href="./form/field-radio.html">radio 列表</a>）支持将描述作为其 <code>options</code> 值的一部分。这里值被定义为另一个数组，语法为 <code>key: [label, description]</code>。</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">options</span><span class="token punctuation">:</span>
    <span class="token key atrule">all</span><span class="token punctuation">:</span> <span class="token punctuation">[</span>All<span class="token punctuation">,</span> Guests and customers will be able to access this page.<span class="token punctuation">]</span>
    <span class="token key atrule">registered</span><span class="token punctuation">:</span> <span class="token punctuation">[</span>Registered only<span class="token punctuation">,</span> Only logged in member will be able to access this page.<span class="token punctuation">]</span>
    <span class="token key atrule">guests</span><span class="token punctuation">:</span> <span class="token punctuation">[</span>Guests only<span class="token punctuation">,</span> Only guest users will be able to access this page.<span class="token punctuation">]</span>
</code></pre></div><p>其他字段，如<a href="./form/field-dropdown.html">下拉列表字段</a>，支持将图标、图片或颜色作为其 <code>options</code> 值的一部分。如果数组中的第二项以 <code>#</code> 开头，则视为颜色；如果值包含 <code>.</code>，则视为图片；否则视为图标类。</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">options</span><span class="token punctuation">:</span>
    <span class="token key atrule">red</span><span class="token punctuation">:</span> <span class="token punctuation">[</span>Color<span class="token punctuation">,</span> <span class="token string">&#39;#ff0000&#39;</span><span class="token punctuation">]</span>
    <span class="token key atrule">icon</span><span class="token punctuation">:</span> <span class="token punctuation">[</span>Icon<span class="token punctuation">,</span> <span class="token string">&#39;oc-icon-calendar&#39;</span><span class="token punctuation">]</span>
    <span class="token key atrule">image</span><span class="token punctuation">:</span> <span class="token punctuation">[</span>Image<span class="token punctuation">,</span> <span class="token string">&#39;/path/to/image.png&#39;</span><span class="token punctuation">]</span>
</code></pre></div><h2 id="选项预设"><a href="#选项预设" class="header-anchor">#</a> 选项预设</h2><p><code>optionsPreset</code> 属性指定可用于请求可用选项的预设代码。</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">optionsPreset</span><span class="token punctuation">:</span> icons
</code></pre></div><p>以下预设可用：</p><div class="table"><table tabindex="0"><thead><tr><th>预设</th><th>描述</th></tr></thead><tbody><tr><td><strong>icons</strong></td><td>列出可用的图标名称（例如：<code>icon-calendar</code>）</td></tr><tr><td><strong>phosphorIcons</strong></td><td>列出可用的图标名称（例如：<code>ph ph-calendar</code>）</td></tr><tr><td><strong>locales</strong></td><td>列出可用的语言区域（例如：<code>en-au</code>）</td></tr><tr><td><strong>flags</strong></td><td>列出语言区域及其图标标志（例如：<code>[en-au, flag-au]</code>）</td></tr><tr><td><strong>timezones</strong></td><td>列出可用的时区（例如：<code>Australia/Sydney</code>）</td></tr></tbody></table></div><h2 id="选项方法"><a href="#选项方法" class="header-anchor">#</a> 选项方法</h2><p><code>optionsMethod</code> 属性指定一个可调用的 PHP 方法，用于请求可用选项。通常，方法名称将引用关联模型的本地方法。</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">optionsMethod</span><span class="token punctuation">:</span> getMyOptionsFromModel
</code></pre></div><p>方法名称也可以是任何对象上的静态方法。</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">optionsMethod</span><span class="token punctuation">:</span> MyAuthor\\MyPlugin\\Helpers\\FormHelper<span class="token punctuation">:</span><span class="token punctuation">:</span>getMyStaticMethodOptions
</code></pre></div><h3 id="详细选项定义"><a href="#详细选项定义" class="header-anchor">#</a> 详细选项定义</h3><p>在方法内部，可以使用详细定义来指定更高级的选项，例如为每个选项设置单独的属性。详细定义通过其关联的数组结构来标识。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">getDetailedFieldOptions</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token keyword">return</span> <span class="token punctuation">[</span>
        <span class="token number">1</span> <span class="token operator">=&gt;</span> <span class="token punctuation">[</span>
            <span class="token string single-quoted-string">&#39;label&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;Option 1&#39;</span><span class="token punctuation">,</span>
            <span class="token string single-quoted-string">&#39;comment&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;This is option one&#39;</span>
        <span class="token punctuation">]</span><span class="token punctuation">,</span>
        <span class="token number">2</span> <span class="token operator">=&gt;</span> <span class="token punctuation">[</span>
            <span class="token string single-quoted-string">&#39;label&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;Option 2&#39;</span><span class="token punctuation">,</span>
            <span class="token string single-quoted-string">&#39;comment&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;This is option two&#39;</span><span class="token punctuation">,</span>
            <span class="token string single-quoted-string">&#39;disabled&#39;</span> <span class="token operator">=&gt;</span> <span class="token constant boolean">true</span>
        <span class="token punctuation">]</span>
    <span class="token punctuation">]</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><p>在可能的情况下，支持以下属性：</p><div class="table"><table tabindex="0"><thead><tr><th>属性</th><th>描述</th></tr></thead><tbody><tr><td><strong>label</strong></td><td>向用户显示选项时使用的名称。</td></tr><tr><td><strong>comment</strong></td><td>在选项标签下方放置描述性注释。</td></tr><tr><td><strong>readOnly</strong></td><td>指定选项是否为只读。</td></tr><tr><td><strong>disabled</strong></td><td>指定选项是否被禁用。</td></tr><tr><td><strong>hidden</strong></td><td>定义选项但从不显示它。</td></tr><tr><td><strong>color</strong></td><td>以十六进制颜色定义选项的状态指示器颜色（下拉列表）</td></tr><tr><td><strong>icon</strong></td><td>为此选项指定图标名称（下拉列表）</td></tr><tr><td><strong>image</strong></td><td>为此选项指定图片 URL（下拉列表）</td></tr><tr><td><strong>optgroup</strong></td><td>如果子项应属于选项组结构，则设置为 <code>true</code>，默认值：<code>false</code>（下拉列表）</td></tr><tr><td><strong>children</strong></td><td>将子选项指定为另一个数组以形成嵌套结构（复选框列表）</td></tr></tbody></table></div><p>如果选项定义支持嵌套，请使用 <code>children</code> 属性。通常，这将为复选框列表显示结构，并为下拉列表实现选项组。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">getDetailedFieldOptions</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token keyword">return</span> <span class="token punctuation">[</span>
        <span class="token number">1</span> <span class="token operator">=&gt;</span> <span class="token punctuation">[</span>
            <span class="token string single-quoted-string">&#39;label&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;Option 1&#39;</span><span class="token punctuation">,</span>
            <span class="token string single-quoted-string">&#39;comment&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;This is option one&#39;</span><span class="token punctuation">,</span>
            <span class="token string single-quoted-string">&#39;children&#39;</span> <span class="token operator">=&gt;</span> <span class="token punctuation">[</span>
                <span class="token number">2</span> <span class="token operator">=&gt;</span> <span class="token punctuation">[</span>
                    <span class="token string single-quoted-string">&#39;label&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;Option 2&#39;</span><span class="token punctuation">,</span>
                    <span class="token string single-quoted-string">&#39;comment&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;This is option two&#39;</span><span class="token punctuation">,</span>
                <span class="token punctuation">]</span><span class="token punctuation">,</span>
                <span class="token comment">// ...</span>
            <span class="token punctuation">]</span>
        <span class="token punctuation">]</span><span class="token punctuation">,</span>
    <span class="token punctuation">]</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><h4 id="另请参阅"><a href="#另请参阅" class="header-anchor">#</a> 另请参阅</h4><div class="custom-block also"><ul><li><a href="./form/field-checkboxlist.html">Checkbox List 字段</a></li><li><a href="./form/field-dropdown.html">Dropdown 字段</a></li><li><a href="./form/field-radio.html">Radio 字段</a></li></ul></div>`,29))])}const b=o(r,[["render",d]]);export{f as __pageData,b as default};
